-- rowstile 0.1.0-alpha.9: policy. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- rowstile 0.1.0-alpha.7 -> 0.1.0-alpha.9: what the new version makes differently

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '64fa4b0cce59c2f2', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '64fa4b0cce59c2f2' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '64fa4b0cce59c2f2' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_attribute
             WHERE attrelid = to_regclass('authz.policy_versions') AND attname = 'lock' AND NOT attisdropped) THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '64fa4b0cce59c2f2' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM 'c1f5af7887a31a4b' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      'c1f5af7887a31a4b', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- the row triggers given to tables that inherit: made again below, on what this migration makes
DO $authz_ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT g.tgname, g.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger g
           JOIN pg_catalog.pg_description d ON d.objoid = g.oid AND d.classoid = 'pg_catalog.pg_trigger'::regclass
           WHERE d.description = 'rowstile: the trigger of the table above, for the rows stored here' LOOP
    EXECUTE pg_catalog.format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_ch$;

-- what goes, or is made again
DROP TRIGGER IF EXISTS "authz_update_1" ON "app"."documents";
DROP FUNCTION IF EXISTS
  authz_gen."app.documents:column_1:holds"(p_row "app"."documents"),
  authz_gen."app.documents:column_1:items"(p_row "app"."documents");
DROP FUNCTION IF EXISTS
  authz_gen."app.documents:column_1:why"(p_row "app"."documents"),
  authz_gen."app.documents:update:why"(p_row "app"."documents"),
  authz_int."document__update_1"();

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- a row for each row a share, a key or a request named (authz_int.mark_row), until that row is gone
CREATE TABLE authz_int.row_marks (type text, id text, n bigint NOT NULL DEFAULT 0, PRIMARY KEY (type, id));

-- custom roles, access requests, access reviews, break-glass, a key of one's own and view-as are for users: a
-- service signed in (another principal type) is refused, saying so, even one the policy gives the permission the
-- call asks for
CREATE FUNCTION authz_int.users_only(p_what text) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_type text; v_id text;
BEGIN
  SELECT p.principal_type, p.principal_id INTO v_type, v_id FROM authz.principal() p;
  IF v_type <> 'user' THEN
    RAISE EXCEPTION '% is for users, not services (% % is signed in)', p_what, v_type, v_id
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ715';
  END IF;
END $f$;

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', 'applying the policy: the row was deleted', true); END $r$;

-- Shares stored with ids that aren't canonical ('007', an uppercase uuid: written directly before every
-- write went through authz_int.canon) are made canonical, since the sweep below and the triggers compare
-- text; one that then repeats a share already stored goes, the first made staying
CREATE TEMP TABLE authz_uncanonical ON COMMIT DROP AS
  SELECT g.ctid AS row, authz_int.canon(g.object_type, g.object_id) AS object_id,
         authz_int.canon(g.subject_type, g.subject_id) AS subject_id
  FROM authz.shares g
  WHERE g.object_id IS DISTINCT FROM authz_int.canon(g.object_type, g.object_id)
     OR g.subject_id IS DISTINCT FROM authz_int.canon(g.subject_type, g.subject_id);
DELETE FROM authz.shares g USING authz_uncanonical u
WHERE g.ctid = u.row AND EXISTS (
  SELECT 1 FROM authz.shares c WHERE c.object_type = g.object_type AND c.object_id = u.object_id AND c.relation = g.relation
    AND c.subject_type = g.subject_type AND c.subject_id = u.subject_id AND c.subject_relation = g.subject_relation);
DELETE FROM authz.shares g USING (
  SELECT u.row, row_number() OVER (PARTITION BY s.object_type, u.object_id, s.relation, s.subject_type, u.subject_id,
                                   s.subject_relation ORDER BY s.created_at, u.row) AS n
  FROM authz_uncanonical u JOIN authz.shares s ON s.ctid = u.row) d
WHERE g.ctid = d.row AND d.n > 1;
UPDATE authz.shares g SET object_id = u.object_id, subject_id = u.subject_id FROM authz_uncanonical u WHERE g.ctid = u.row;
DROP TABLE authz_uncanonical;

-- Shares on rows that no longer exist (deleted while no trigger watched them) are dropped
DELETE FROM authz.shares g WHERE g.object_type = 'user' AND NOT EXISTS (SELECT 1 FROM "app"."users" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'user' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "app"."users" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'team' AND NOT EXISTS (SELECT 1 FROM "app"."teams" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'team' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "app"."teams" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'document' AND NOT EXISTS (SELECT 1 FROM "app"."documents" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'document' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "app"."documents" x WHERE x."id"::text = g.subject_id);
-- ...and so are the API keys of principals that no longer exist
DELETE FROM authz.api_keys k WHERE k.principal_type = 'user' AND NOT EXISTS (SELECT 1 FROM "app"."users" x WHERE x."id"::text = k.user_id);
-- ...and pending access requests whose requester no longer exists are cancelled (not those whose object
-- doesn't: a request for a missing object is allowed, so that asking doesn't tell which hidden ones exist)
UPDATE authz.requests r SET status = 'cancelled', decided_at = now(), note = 'its requester is gone' WHERE r.status = 'pending' AND NOT EXISTS (SELECT 1 FROM "app"."users" x WHERE x."id"::text = r.requester);

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', '', true); END $r$;

-- a share, a key or a request naming a row marks it (a new version of its mark, which a transaction that can't
-- see it and then deletes the row, or changes its id, writes too: forget_marks)
CREATE FUNCTION authz_int.mark_row(p_type text, p_id text) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  INSERT INTO authz_int.row_marks AS m (type, id) VALUES (p_type, p_id)
  ON CONFLICT (type, id) DO UPDATE SET n = m.n + 1 $f$;

-- rows that are gone, or whose id changed: their marks go too. In a transaction whose snapshot may be older than a
-- share, key or request naming one of them (not READ COMMITTED), the marks are written first: if one was made since,
-- that fails to serialize (40001), rather than leave what the deletes after can't see
CREATE FUNCTION authz_int.forget_marks(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    INSERT INTO authz_int.row_marks AS m (type, id) SELECT DISTINCT p_type, x FROM unnest(p_ids) x
    ON CONFLICT (type, id) DO UPDATE SET n = m.n + 1;
  END IF;
  DELETE FROM authz_int.row_marks WHERE type = p_type AND id = ANY (p_ids);
END $f$;

-- whether a row is there, locked (FOR KEY SHARE) until the transaction ends, as authz.share locks what it shares
CREATE FUNCTION authz_int.hold(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_tbl text; v_find text; v_found boolean;
BEGIN
  SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_type;
  -- (the key's type by a subquery, never a variable: pg_input_is_valid takes a variable's first value for every
  -- later call from the same line, so a uuid key checked after a bigint one would be invalid)
  IF v_tbl IS NULL OR NOT pg_catalog.pg_input_is_valid(p_id, (SELECT t.keytype FROM authz_int.types t WHERE t.name = p_type)) THEN
    RETURN false;
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find) INTO v_found USING p_id;
  RETURN v_found;
END $f$;

-- shares on user rows that are gone, or whose id changed, are removed (and their marks: forget_marks), and
-- the pending requests naming them are cancelled (requests_gone)
CREATE OR REPLACE FUNCTION authz_int."user__forget"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    DELETE FROM authz.shares WHERE object_type = 'user';
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id <> '*';      -- '*' (every one signed in) names no row
    DELETE FROM authz_int.row_marks WHERE type = 'user';
    PERFORM authz_int.requests_gone('user', NULL);
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.forget_marks('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
    DELETE FROM authz.shares WHERE object_type = 'user' AND object_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
    PERFORM authz_int.requests_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.forget_marks('user', ARRAY(SELECT o."id"::text FROM old_rows o));
    DELETE FROM authz.shares WHERE object_type = 'user' AND object_id IN (SELECT o."id"::text FROM old_rows o);
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id IN (SELECT o."id"::text FROM old_rows o);
    PERFORM authz_int.requests_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."user__forget_id"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  PERFORM authz_int.forget_marks('user', ARRAY[OLD."id"::text]);
  DELETE FROM authz.shares WHERE object_type = 'user' AND object_id = OLD."id"::text;
  DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id = OLD."id"::text;
  PERFORM authz_int.requests_gone('user', ARRAY[OLD."id"::text]);
  RETURN NULL;
END $f$;

-- before TRUNCATE empties the table: with a snapshot older than a share on one of its rows, fail to serialize
CREATE FUNCTION authz_int."user__forget_all"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    PERFORM authz_int.forget_marks('user', ARRAY(SELECT x."id"::text FROM "app"."users" x));
  END IF;
  RETURN NULL;
END $f$;

CREATE TRIGGER "authz_user_forget_trunc_first" BEFORE TRUNCATE ON "app"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__forget_all"();

