CREATE FUNCTION authz_gen."app.documents:update:why"(p_row "app"."documents", p_stored boolean) RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.documents:update:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update : edit  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.documents update'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow update on app.documents'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'edit';
  IF NOT v[4] AND p_stored THEN
    RETURN QUERY SELECT '    ' || l FROM authz.explain('document', ((p_row)."id"::text), 'edit') l LIMIT 20;
  END IF;
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."app.documents:update:refuse"(p_row "app"."documents") RETURNS boolean
LANGUAGE plpgsql VOLATILE SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_who text := CASE WHEN coalesce(current_setting('authz.user_id', true), '') = '' THEN 'someone not signed in'
  ELSE coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || current_setting('authz.user_id', true) END;
BEGIN
  BEGIN
    v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."app.documents:update:why"(p_row, false) l);
  EXCEPTION WHEN OTHERS THEN
    v_lines := 'no explanation: ' || SQLERRM;
  END;
  RAISE EXCEPTION USING ERRCODE = 'insufficient_privilege', MESSAGE = 'permission denied: ' || v_who || ' may not ' || 'update this row of app.documents to these values',
    DETAIL = v_lines, SCHEMA = 'app', TABLE = 'documents', CONSTRAINT = 'authz_update',
    HINT = 'the update rule must hold on the row after the change too (Postgres checks both) (rowstile help AZ709)';
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."app.documents:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "app"."documents"; r_new "app"."documents";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."app.documents:insert:why"(jsonb_populate_record(NULL::"app"."documents", coalesce(p_row, '{}'))));
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'app.documents', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT x.* INTO r_old FROM "app"."documents" x WHERE x."id" = p_id::bigint;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."app.documents:delete:why"(r_old));
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY(SELECT * FROM authz_gen."app.documents:update:why"(r_old, true)) || CASE WHEN p_row IS NULL THEN '{}'::text[] ELSE ARRAY['after the change:'] || ARRAY(SELECT '  ' || l FROM authz_gen."app.documents:update:why"(r_new, false) l) END;
END $f$;

CREATE FUNCTION authz_gen."app.documents:column owner_id:items"(p_row "app"."documents") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce(coalesce((false), false), false),
    coalesce((SELECT authz_int.scope_cmd('app.documents', 'update')), false),
    coalesce(true, false),
    coalesce(coalesce((false), false), false)]
  FROM (SELECT (p_row).*) AS "documents";
END;

CREATE FUNCTION authz_gen."app.documents:column owner_id:why"(p_row "app"."documents") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.documents:column owner_id:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update owner_id : nobody  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.documents update owner_id'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow update on app.documents'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'nobody';
END $f$;

-- app.documents update owner_id (line 23): nobody
-- Whether the rule holds for a row. BEGIN ATOMIC, as the refusals' functions are: the trigger below runs as the app
-- role, which can't name what is in authz_int in text read at run time (the signed-in service, authz_int."<type>__me")
CREATE FUNCTION authz_gen."app.documents:column owner_id:holds"(p_row "app"."documents") RETURNS boolean
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT coalesce(coalesce((false), false), false) FROM (SELECT (p_row).*) AS "documents";
END;

-- checked on the row before the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too)
CREATE FUNCTION authz_int."app.documents:column owner_id"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_row "app"."documents";
BEGIN
  IF pg_catalog.row_security_active('"app"."documents"'::pg_catalog.regclass) THEN
    -- the row as the table's own: a partition's columns may be in another order, a table that inherits may have more
    IF TG_RELID = '"app"."documents"'::pg_catalog.regclass THEN v_row := OLD;
    ELSE v_row := pg_catalog.jsonb_populate_record(NULL::"app"."documents", pg_catalog.to_jsonb(OLD)); END IF;
    IF NOT authz_gen."app.documents:column owner_id:holds"(v_row) THEN
      BEGIN
        v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."app.documents:column owner_id:why"(v_row) l);
      EXCEPTION WHEN OTHERS THEN
        v_lines := 'no explanation: ' || SQLERRM;
      END;
      RAISE EXCEPTION 'changing owner_id of app.documents % needs: nobody', OLD."id" USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
        SCHEMA = 'app', TABLE = 'documents', CONSTRAINT = 'authz_update', HINT = 'rowstile help AZ709';
    END IF;
  END IF;
  RETURN NEW;
END $f$;

CREATE TRIGGER "authz_update owner_id" BEFORE UPDATE ON "app"."documents" FOR EACH ROW
  WHEN (OLD."owner_id" IS DISTINCT FROM NEW."owner_id")
  EXECUTE FUNCTION authz_int."app.documents:column owner_id"();

-- Share: needs the relation's 'shared by' permission on the object, and every permission
-- the relation grants (you can't grant more than you hold); the subject must exist
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '',
  p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_tbl text; v_find text; v_found boolean; v_key text; v_rel authz_int.shared_relations; v_need text;
        v_role authz.roles;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- lock the object (FOR KEY SHARE): a concurrent delete waits for us, or we for it
  SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_type;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707'; END IF;
  IF NOT pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find) INTO v_found USING p_id;
  -- a caller who may share nothing on the object gets the answer a missing object gets (this same RAISE),
  -- before the subject and the relation are looked at: sharing never tells a hidden object from a missing one
  v_found := v_found AND EXISTS (
    SELECT 1 FROM (SELECT s.shared_by AS perm FROM authz_int.shared_relations s WHERE s.object_type = p_type
                   UNION SELECT 'share') x
    -- (CASE: authz.can raises for a permission the type doesn't have, and AND doesn't say which runs first)
    WHERE CASE WHEN EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = x.perm)
               THEN authz.can(p_type, p_id, x.perm) ELSE false END);
  IF NOT v_found THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  v_key := CASE WHEN p_subject_type IN ('anyone', 'link') THEN p_subject_type
                WHEN p_subject_id = '*' AND p_subject_relation = '' THEN p_subject_type || ':*'
                WHEN p_subject_relation <> '' THEN p_subject_type || '#' || p_subject_relation
                ELSE p_subject_type END;
  -- the subject must exist (and is locked, like the object)
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_subject_type;
    v_found := v_tbl IS NOT NULL AND pg_catalog.pg_input_is_valid(p_subject_id,
                 (SELECT keytype FROM authz_int.types WHERE name = p_subject_type));
    IF v_found THEN
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find)
        INTO v_found USING p_subject_id;
    END IF;
    IF NOT v_found THEN
      RAISE EXCEPTION 'there is no % %', p_subject_type, p_subject_id USING HINT = 'rowstile help AZ708';
    END IF;
  END IF;
  IF p_relation LIKE 'role:%' THEN
    -- a custom role: its type must match, the subject must be allowed, and you must hold all it grants
    SELECT * INTO v_role FROM authz.roles WHERE 'role:' || id = p_relation;
    IF v_role.id IS NULL OR v_role.object_type <> p_type THEN
      RAISE EXCEPTION 'no role % for %', p_relation, p_type USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT authz_int.role_owned(p_type, p_id, v_role.owner_type, v_role.owner_id) THEN
      RAISE EXCEPTION 'role % belongs to % %, which doesn''t own % %', v_role.name, v_role.owner_type, v_role.owner_id,
        p_type, p_id USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_type AND subject = v_key) THEN
      RAISE EXCEPTION 'custom roles on % cannot be given to %', p_type, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share')
       OR NOT authz.can(p_type, p_id, 'share') THEN
      RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(permission, ', ') INTO v_need FROM authz.role_permissions
    WHERE role_id = v_role.id AND NOT authz.can(p_type, p_id, permission);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot give role % on % %: you do not hold %', v_role.name, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
  ELSE
    SELECT * INTO v_rel FROM authz_int.shared_relations s
    WHERE s.object_type = p_type AND s.relation = p_relation AND s.subject = v_key;
    IF v_rel.relation IS NULL THEN
      RAISE EXCEPTION 'the policy does not allow sharing %.% with %', p_type, p_relation, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_rel.shared_by)
       OR NOT authz.can(p_type, p_id, v_rel.shared_by) THEN
      RAISE EXCEPTION 'you cannot share % % (needs %)', p_type, p_id, v_rel.shared_by USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(n, ', ') INTO v_need FROM unnest(v_rel.required) n WHERE NOT authz.can(p_type, p_id, n);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot grant %.% on % %: you do not hold %', p_type, p_relation, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    IF NOT authz_int.share_if(p_type || '.' || p_relation || '.' || v_key, p_id, p_subject_type,
                              p_subject_id, p_subject_relation) THEN
      RAISE EXCEPTION 'the policy does not allow this share (%)', coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = v_rel.loc), '?') USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
  END IF;
  IF p_caveat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM authz_int.caveats WHERE name = p_caveat) THEN
    RAISE EXCEPTION 'no caveat % in the policy', p_caveat USING HINT = 'rowstile help AZ707';
  END IF;
  PERFORM authz_int.mark_row(p_type, p_id);
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    PERFORM authz_int.mark_row(p_subject_type, p_subject_id);
  END IF;
  INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                            expires_at, created_by, starts_at, caveat, caveat_args)
  VALUES (p_type, p_id, p_relation, p_subject_type, p_subject_id, p_subject_relation,
          p_expires_at, authz_int.actor(), p_starts_at, p_caveat, p_caveat_args)
  ON CONFLICT ON CONSTRAINT shares_pkey
  DO UPDATE SET expires_at = EXCLUDED.expires_at, created_by = EXCLUDED.created_by,
                starts_at = EXCLUDED.starts_at, caveat = EXCLUDED.caveat, caveat_args = EXCLUDED.caveat_args;
END $f$;

-- Custom roles: defined per owner (e.g. an org) by people with 'manage_roles' there
CREATE OR REPLACE FUNCTION authz.create_role(p_owner_type text, p_owner_id text, p_object_type text, p_name text,
  p_permissions text[]) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id bigint; v_bad text;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.create_role');
  IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'manage_roles') THEN
    RAISE EXCEPTION '% has no manage_roles permission in the policy', p_owner_type USING HINT = 'rowstile help AZ707';
  END IF;
  -- a type without `roles` (or one the policy doesn't have): a role there would be one nobody can be given
  IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_object_type) THEN
    RAISE EXCEPTION 'no custom roles on % in the policy', p_object_type USING HINT = 'rowstile help AZ707';
  END IF;
  IF authz.uid() IS NULL OR NOT authz.can(p_owner_type, p_owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage roles of % %', p_owner_type, p_owner_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF p_owner_type IS DISTINCT FROM coalesce(authz_int.role_owner_type(p_object_type), p_owner_type) THEN
    RAISE EXCEPTION 'custom roles on % belong to a % (the policy says where they come from), not to a %',
      p_object_type, authz_int.role_owner_type(p_object_type), p_owner_type USING HINT = 'rowstile help AZ706';
  END IF;
  SELECT string_agg(p, ', ') INTO v_bad FROM unnest(p_permissions) p
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.role_grantable g WHERE g.object_type = p_object_type AND g.permission = p);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'custom roles on % cannot grant %', p_object_type, v_bad USING HINT = 'rowstile help AZ706';
  END IF;
  INSERT INTO authz.roles (owner_type, owner_id, object_type, name, created_by)
  VALUES (p_owner_type, authz_int.canon(p_owner_type, p_owner_id), p_object_type, p_name, authz.uid()::text)
  RETURNING id INTO v_id;
  INSERT INTO authz.role_permissions SELECT v_id, p FROM unnest(p_permissions) p ON CONFLICT DO NOTHING;
  RETURN v_id;
END $f$;

CREATE OR REPLACE FUNCTION authz.set_role_permissions(p_role bigint, p_permissions text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.roles; v_bad text;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.set_role_permissions');
  SELECT * INTO v FROM authz.roles WHERE id = p_role;
  IF v.id IS NULL OR authz.uid() IS NULL OR NOT authz.can(v.owner_type, v.owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage role %', p_role USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  SELECT string_agg(p, ', ') INTO v_bad FROM unnest(p_permissions) p
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.role_grantable g WHERE g.object_type = v.object_type AND g.permission = p);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'custom roles on % cannot grant %', v.object_type, v_bad USING HINT = 'rowstile help AZ706'; END IF;
  DELETE FROM authz.role_permissions WHERE role_id = p_role;
  INSERT INTO authz.role_permissions SELECT p_role, p FROM unnest(p_permissions) p ON CONFLICT DO NOTHING;
END $f$;

CREATE OR REPLACE FUNCTION authz.delete_role(p_role bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.roles;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.delete_role');
  SELECT * INTO v FROM authz.roles WHERE id = p_role;
  IF v.id IS NULL OR authz.uid() IS NULL OR NOT authz.can(v.owner_type, v.owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage role %', p_role USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  DELETE FROM authz.roles WHERE id = p_role;
END $f$;

CREATE OR REPLACE FUNCTION authz.roles_of(p_owner_type text, p_owner_id text)
RETURNS TABLE (id bigint, object_type text, name text, permissions text[])
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM authz_int.users_only('authz.roles_of');
  IF authz.uid() IS NULL OR NOT (
       (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'manage_roles')
        AND authz.can(p_owner_type, p_owner_id, 'manage_roles'))
    OR (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'view')
        AND authz.can(p_owner_type, p_owner_id, 'view'))) THEN
    RAISE EXCEPTION 'you cannot see roles of % %', p_owner_type, p_owner_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT r.id, r.object_type, r.name,
    ARRAY(SELECT p.permission FROM authz.role_permissions p WHERE p.role_id = r.id ORDER BY 1)
    FROM authz.roles r WHERE r.owner_type = p_owner_type AND r.owner_id = p_owner_id ORDER BY r.id;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."document__editor__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'editor' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    RETURN NEXT pad || 'yes  ' || 'editor: shared with you' || coalesce((SELECT concat(' (by ', coalesce(g.created_by, 'an admin'), coalesce(', until ' || g.expires_at, ''), coalesce(', from ' || g.starts_at, ''), coalesce(', caveat ' || g.caveat, ''), ')') FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = p_id::text AND g.relation = 'editor' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL ORDER BY g.created_at LIMIT 1), '');
    RETURN;
  END IF;
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'editor' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    FOR v_t IN SELECT x.gid::text AS gid FROM (SELECT g.subject_id AS gid FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = p_id::text AND g.relation = 'editor' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) x LIMIT 1 LOOP
      RETURN NEXT pad || 'yes  ' || 'editor: shared with' || ' team ' || v_t.gid || ', and you are member there';
      RETURN QUERY SELECT * FROM authz_int."team__member__why"(v_t.gid::bigint, p_depth + 1, p_seen);
    END LOOP;
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold document.editor';
END $f$;

CREATE OR REPLACE FUNCTION authz_int."document__viewer__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    RETURN NEXT pad || 'yes  ' || 'viewer: shared with you' || coalesce((SELECT concat(' (by ', coalesce(g.created_by, 'an admin'), coalesce(', until ' || g.expires_at, ''), coalesce(', from ' || g.starts_at, ''), coalesce(', caveat ' || g.caveat, ''), ')') FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = p_id::text AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL ORDER BY g.created_at LIMIT 1), '');
    RETURN;
  END IF;
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'viewer' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    FOR v_t IN SELECT x.gid::text AS gid FROM (SELECT g.subject_id AS gid FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = p_id::text AND g.relation = 'viewer' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) x LIMIT 1 LOOP
      RETURN NEXT pad || 'yes  ' || 'viewer: shared with' || ' team ' || v_t.gid || ', and you are member there';
      RETURN QUERY SELECT * FROM authz_int."team__member__why"(v_t.gid::bigint, p_depth + 1, p_seen);
    END LOOP;
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold document.viewer';
END $f$;

-- the keys of principals that are gone, or whose id changed (p_ids; NULL: every one of the type, TRUNCATE) are
-- deleted, each in the audit trail, with the rows' marks (forget_marks: in a transaction whose snapshot may be older
-- than a key made for one of them, that fails to serialize, 40001)
CREATE FUNCTION authz_int.keys_gone(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k record;
BEGIN
  IF p_ids IS NULL THEN
    DELETE FROM authz_int.row_marks WHERE type = p_type;
  ELSE
    PERFORM authz_int.forget_marks(p_type, p_ids);
  END IF;
  FOR k IN DELETE FROM authz.api_keys WHERE principal_type = p_type AND (p_ids IS NULL OR user_id = ANY (p_ids))
           RETURNING id, user_id, name LOOP
    PERFORM authz_int.audit('delete_api_key', p_type, k.user_id, NULL, NULL, NULL, NULL,
                            jsonb_build_object('key', k.id, 'name', k.name, 'why', 'its principal is gone'));
  END LOOP;
END $f$;

-- API keys: a signed-in user's own, or a principal's (a service's) made by someone holding
-- manage_keys on it; only a hash is kept
CREATE OR REPLACE FUNCTION authz.create_api_key(p_name text, p_scopes text DEFAULT '', p_expires_at timestamptz DEFAULT NULL,
  p_principal_type text DEFAULT NULL, p_principal_id text DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_token text := 'ak_' || replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
        v_scopes text[] := ARRAY(SELECT DISTINCT btrim(x) FROM unnest(string_to_array(coalesce(p_scopes, ''), ',')) x
                                 WHERE btrim(x) <> '' ORDER BY 1);
        v_cur text[] := authz_int.scopes_active(); v_bad text;
        v_type text := coalesce(p_principal_type, 'user'); v_id text;
BEGIN
  PERFORM authz_int.check_writable();
  -- the principal's row is locked (FOR KEY SHARE) before it is checked: a delete of it waits for this key, or this
  -- for the delete, which leaves no principal to make it for (a delete with an older snapshot: keys_gone)
  IF p_principal_id IS NULL THEN
    PERFORM authz_int.users_only('authz.create_api_key for oneself');
    v_id := authz.uid()::text;
    IF v_type <> 'user' OR v_id IS NULL OR NOT authz_int.hold('user', v_id) THEN
      RAISE EXCEPTION 'sign in to create an API key' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ714';
    END IF;
  ELSE
    v_id := authz_int.canon(v_type, p_principal_id);
    PERFORM authz_int.hold(v_type, v_id);
    PERFORM authz_int.check_manage_keys(v_type, v_id);
  END IF;
  SELECT string_agg(x, ', ') INTO v_bad FROM unnest(v_scopes) x
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.scope_items WHERE scope = x);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'no scope % in the policy', v_bad USING HINT = 'rowstile help AZ707'; END IF;
  IF v_cur IS NOT NULL AND (cardinality(v_scopes) = 0 OR NOT v_scopes <@ v_cur) THEN
    RAISE EXCEPTION 'a key cannot have more scopes than the session creating it' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  INSERT INTO authz.api_keys (user_id, principal_type, name, prefix, hash, scopes, expires_at)
  VALUES (v_id, v_type, p_name, left(v_token, 10), encode(sha256(convert_to(v_token, 'UTF8')), 'hex'),
          array_to_string(v_scopes, ','), p_expires_at);
  PERFORM authz_int.mark_row(v_type, v_id);
  PERFORM authz_int.audit('create_api_key', v_type, v_id, NULL, NULL, NULL, NULL,
                          jsonb_build_object('name', p_name, 'scopes', v_scopes, 'expires_at', p_expires_at));
  RETURN v_token;
END $f$;

-- Support staff see what a user sees, read-only, for this transaction, with a reason on record:
-- SELECT authz.view_as('42', 'ticket 1234')  (the user type has no impersonate permission: administrators only)
CREATE OR REPLACE FUNCTION authz.view_as(p_user text, p_reason text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := nullif(current_setting('authz.user_id', true), '');
        v_pt text := coalesce(current_setting('authz.principal_type', true), ''); v_actor text := authz_int.actor();
BEGIN
  PERFORM authz_int.users_only('authz.view_as');
  IF coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'already viewing as someone' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'say why (the reason is kept in the audit trail)' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF NOT (authz_int.caller_is_admin()
          ) THEN
    RAISE EXCEPTION 'you cannot view as user %', p_user USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  PERFORM set_config('authz.user_id', coalesce(authz_int.canon('user', p_user), ''), true);
  PERFORM set_config('authz.principal_type', '', true);
  PERFORM authz_int.sign();
  IF authz.uid() IS NULL THEN
    PERFORM set_config('authz.user_id', coalesce(v_me, ''), true);
    PERFORM set_config('authz.principal_type', v_pt, true);
    PERFORM authz_int.sign();
    RAISE EXCEPTION 'there is no active user %', p_user USING HINT = 'rowstile help AZ708';
  END IF;
  PERFORM set_config('authz.acting_user', coalesce(v_actor, authz_int.caller_role()), true);
  PERFORM set_config('authz.scopes', 'read', true);
  PERFORM authz_int.sign();
  PERFORM set_config('authz_ctx.reason', p_reason, true);
  PERFORM authz_int.jit_off();
  PERFORM authz_int.audit('view_as', 'user', authz_int.canon('user', p_user), NULL, NULL, NULL, NULL, NULL);
END $f$;

-- the API keys of user rows that are gone, or whose id changed, are deleted (authz_int.keys_gone)
CREATE FUNCTION authz_int."user__keys_gone"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    PERFORM authz_int.keys_gone('user', NULL);
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

CREATE FUNCTION authz_int."user__keys_gone_id"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  PERFORM authz_int.keys_gone('user', ARRAY[OLD."id"::text]);
  RETURN NULL;
END $f$;

-- before TRUNCATE empties the table: with a snapshot older than a key made for one of its rows, fail to serialize
CREATE FUNCTION authz_int."user__keys_gone_all"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT x."id"::text FROM "app"."users" x));
  END IF;
  RETURN NULL;
END $f$;

CREATE TRIGGER "authz_user_keys_gone_del" AFTER DELETE ON "app"."users"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone"();

CREATE TRIGGER "authz_user_keys_gone_id" AFTER UPDATE ON "app"."users" FOR EACH ROW
  WHEN (OLD."id" IS DISTINCT FROM NEW."id") EXECUTE FUNCTION authz_int."user__keys_gone_id"();

CREATE TRIGGER "authz_user_keys_gone_trunc" AFTER TRUNCATE ON "app"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone"();

CREATE TRIGGER "authz_user_keys_gone_trunc_first" BEFORE TRUNCATE ON "app"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone_all"();

-- On a partitioned table, an update that puts a row in another partition is a delete there and an insert here:
-- Postgres runs no AFTER UPDATE row trigger for it. The ids an update leaves no row with lose their keys too.
-- @object trigger "authz_user_keys_gone_moved" ON "app"."users"
-- @if partitioned
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_catalog.pg_class WHERE oid = '"app"."users"'::regclass) = 'p' THEN
    EXECUTE 'CREATE TRIGGER "authz_user_keys_gone_moved" AFTER UPDATE ON "app"."users" REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone"()';
  END IF;
END $tr$;

-- Ask for access: SELECT authz.request_access('folder', '3', 'viewer', 'for the audit', '7 days')
CREATE OR REPLACE FUNCTION authz.request_access(p_type text, p_id text, p_relation text, p_reason text,
  p_duration interval DEFAULT NULL) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id bigint; v_tbl text; v_there boolean;
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.request_access');
  -- the requester's row is locked (FOR KEY SHARE) before it is checked, and the object's if it is there (without
  -- saying whether it is): a delete of either waits for the request, or the request for the delete (then the
  -- requester is nobody, or the object is gone: requests_gone)
  IF authz.uid() IS NOT NULL THEN
    PERFORM authz_int.hold('user', authz.uid()::text);
  END IF;
  IF authz.uid() IS NULL THEN RAISE EXCEPTION 'sign in first' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ714'; END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN RAISE EXCEPTION 'say why you need it' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710'; END IF;
  IF p_duration IS NOT NULL AND p_duration <= interval '0' THEN RAISE EXCEPTION 'the duration must be positive' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710'; END IF;
  SELECT tbl INTO v_tbl FROM authz_int.types WHERE name = p_type;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707'; END IF;
  IF authz_int.manage_perm(p_type, p_relation, CASE WHEN p_relation LIKE 'role:%' THEN NULL ELSE 'user' END) IS NULL
     OR (p_relation LIKE 'role:%' AND NOT EXISTS (SELECT 1 FROM authz_int.role_subjects
                                                  WHERE object_type = p_type AND subject = 'user')) THEN
    RAISE EXCEPTION 'the policy does not allow sharing %.% with a user', p_type, p_relation USING HINT = 'rowstile help AZ706';
  END IF;
  -- no check that the object exists: that would tell people which hidden objects do. A request
  -- for a missing object simply never reaches anyone who could approve it.
  v_there := authz_int.hold(p_type, p_id);
  INSERT INTO authz.requests (object_type, object_id, relation, requester, reason, duration)
  VALUES (p_type, p_id, p_relation, authz.uid()::text, p_reason, p_duration) RETURNING id INTO v_id;
  -- marked: a delete of the requester, or of the object, that can't see this request fails to serialize
  PERFORM authz_int.mark_row('user', authz.uid()::text);
  IF v_there THEN
    PERFORM authz_int.mark_row(p_type, p_id);
  END IF;
  PERFORM authz_int.audit('request_access', p_type, p_id, p_relation, 'user', authz.uid()::text, '',
                          jsonb_build_object('request', v_id, 'duration', p_duration));
  PERFORM pg_notify('authz_requests', v_id::text);
  RETURN v_id;
END $f$;

-- A pending request goes when its requester's row goes, or its object's (deleted, given a new id, emptied out with
-- its table: p_ids NULL), so that it never reaches whoever later has that id; it is kept, cancelled, with why.
-- Decided requests are history, and stay as they were
CREATE FUNCTION authz_int.requests_gone(p_type text, p_ids text[]) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  UPDATE authz.requests r SET status = 'cancelled', decided_at = now(),
    note = CASE WHEN r.object_type = p_type AND (p_ids IS NULL OR r.object_id = ANY (p_ids))
                THEN 'its object is gone' ELSE 'its requester is gone' END
  WHERE r.status = 'pending'
    AND ((r.object_type = p_type AND (p_ids IS NULL OR r.object_id = ANY (p_ids)))
         OR (p_type = 'user' AND (p_ids IS NULL OR r.requester = ANY (p_ids)))) $f$;

-- Requests the current user may decide (they may share that relation on the object), and their own
CREATE OR REPLACE FUNCTION authz.pending_requests()
RETURNS TABLE (id bigint, object_type text, object_id text, relation text, requester text, reason text,
               duration interval, created_at timestamptz, mine boolean)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM authz_int.users_only('authz.pending_requests');
  RETURN QUERY
  SELECT r.id, r.object_type, r.object_id, r.relation, r.requester, r.reason, r.duration, r.created_at,
         r.requester = authz.uid()::text
  FROM authz.requests r
  WHERE r.status = 'pending' AND authz.uid() IS NOT NULL
    AND (r.requester = authz.uid()::text
         OR (r.requester IS DISTINCT FROM authz.uid()::text
             AND authz_int.may_manage(r.object_type, r.object_id, r.relation,
                                      CASE WHEN r.relation LIKE 'role:%' THEN NULL ELSE 'user' END)))
  ORDER BY r.id;
END $f$;

-- Approve (it becomes a share, made by you, that ends after the requested time) or deny
CREATE OR REPLACE FUNCTION authz.decide_request(p_id bigint, p_approve boolean, p_note text DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r authz.requests;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.decide_request');
  IF p_approve IS NULL THEN RAISE EXCEPTION 'approve (true) or deny (false)' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710'; END IF;
  SELECT * INTO r FROM authz.requests WHERE id = p_id AND status = 'pending' FOR UPDATE;
  IF r.id IS NULL THEN RAISE EXCEPTION 'no pending request %', p_id USING HINT = 'rowstile help AZ708'; END IF;
  IF authz.uid() IS NULL OR r.requester = authz.uid()::text THEN
    RAISE EXCEPTION 'you cannot decide your own request' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF NOT authz_int.may_manage(r.object_type, r.object_id, r.relation,
                              CASE WHEN r.relation LIKE 'role:%' THEN NULL ELSE 'user' END) THEN
    RAISE EXCEPTION 'you cannot decide request %', p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF p_approve THEN
    -- authz.share checks again that you may share it, and that you hold what it grants
    PERFORM authz.share(r.object_type, r.object_id, r.relation, 'user', r.requester, '',
                        CASE WHEN r.duration IS NULL THEN NULL ELSE now() + r.duration END);
  END IF;
  UPDATE authz.requests SET status = CASE WHEN p_approve THEN 'approved' ELSE 'denied' END,
    decided_by = authz.uid()::text, decided_at = now(), note = p_note WHERE id = p_id;
  PERFORM authz_int.audit(CASE WHEN p_approve THEN 'approve_request' ELSE 'deny_request' END, r.object_type,
    r.object_id, r.relation, 'user', r.requester, '', jsonb_build_object('request', p_id, 'note', p_note));
END $f$;

CREATE OR REPLACE FUNCTION authz.cancel_request(p_id bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.cancel_request');
  UPDATE authz.requests SET status = 'cancelled', decided_at = now()
  WHERE id = p_id AND status = 'pending' AND requester = authz.uid()::text;
  IF NOT FOUND THEN RAISE EXCEPTION 'no pending request % of yours', p_id USING HINT = 'rowstile help AZ708'; END IF;
END $f$;

-- Emergency access: people who hold 'break_glass' on an object give themselves a relation on it
-- for a short time (one day at most); it is audited and announced on channel authz_alerts
-- (the notification carries the audit row's id; the details stay in authz.audit)
CREATE OR REPLACE FUNCTION authz.break_glass(p_type text, p_id text, p_relation text, p_reason text,
  p_duration interval DEFAULT interval '1 hour') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE g authz.shares; v_until timestamptz; v_audit bigint; v_held boolean;
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.break_glass');
  IF coalesce(btrim(p_reason), '') = '' THEN RAISE EXCEPTION 'say why (it is kept in the audit trail)' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710'; END IF;
  IF p_duration IS NULL OR p_duration <= interval '0' OR p_duration > interval '1 day' THEN
    RAISE EXCEPTION 'emergency access lasts more than nothing and one day at most' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  -- the object and the user are locked (FOR KEY SHARE), as authz.share locks them: a delete waits for this, or this
  -- for it and then finds nothing to break into
  v_held := authz.uid() IS NOT NULL;
  IF v_held THEN v_held := authz_int.hold(p_type, p_id); END IF;
  IF v_held THEN v_held := authz_int.hold('user', authz.uid()::text); END IF;
  IF NOT v_held
     OR NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'break_glass')
     OR NOT authz.can(p_type, p_id, 'break_glass') THEN
    RAISE EXCEPTION 'you cannot break the glass on % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM authz_int.shared_relations WHERE object_type = p_type AND relation = p_relation
                 AND subject = 'user') THEN
    RAISE EXCEPTION 'the policy does not allow sharing %.% with a user', p_type, p_relation USING HINT = 'rowstile help AZ706';
  END IF;
  v_until := now() + p_duration;
  PERFORM set_config('authz_ctx.reason', p_reason, true);
  PERFORM authz_int.mark_row(p_type, p_id);
  PERFORM authz_int.mark_row('user', authz.uid()::text);
  SELECT * INTO g FROM authz.shares WHERE object_type = p_type AND object_id = p_id AND relation = p_relation
    AND subject_type = 'user' AND subject_id = authz.uid()::text AND subject_relation = '' FOR UPDATE;
  IF g.object_id IS NULL THEN
    INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                              expires_at, created_by)
    VALUES (p_type, p_id, p_relation, 'user', authz.uid()::text, '', v_until, authz.uid()::text);
  ELSIF g.caveat IS NOT NULL OR (g.starts_at IS NOT NULL AND g.starts_at > now())
        OR (g.expires_at IS NOT NULL AND g.expires_at < v_until) THEN
    -- a share that would not let them in now becomes an unconditional one until then (the old one is in the audit)
    UPDATE authz.shares SET expires_at = CASE WHEN g.expires_at IS NULL THEN v_until ELSE greatest(g.expires_at, v_until) END,
      starts_at = NULL, caveat = NULL, caveat_args = NULL
    WHERE object_type = p_type AND object_id = p_id AND relation = p_relation
      AND subject_type = 'user' AND subject_id = authz.uid()::text AND subject_relation = '';
  END IF;
  PERFORM authz_int.audit('break_glass', p_type, p_id, p_relation, 'user', authz.uid()::text, '',
                          jsonb_build_object('until', v_until, 'previous_share', CASE WHEN g.object_id IS NULL THEN NULL
                                             ELSE to_jsonb(g) - 'subject_id' END));
  SELECT max(id) INTO v_audit FROM authz.audit WHERE action = 'break_glass' AND txid = txid_current();
  PERFORM pg_notify('authz_alerts', json_build_object('audit_id', v_audit, 'action', 'break_glass')::text);
END $f$;

-- Access reviews: snapshot the shares on an object; reviewers keep or revoke each; closing applies it.
-- Starting one needs 'share' on the object (or being an administrator); revoking an item needs
-- what unsharing it needs.
-- Reviews are for users: a service signed in is refused (users_only).
CREATE OR REPLACE FUNCTION authz.start_review(p_type text, p_id text, p_closes_at timestamptz DEFAULT now() + interval '14 days')
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id bigint;
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.start_review');
  IF NOT authz_int.may_inspect(p_type, p_id) THEN
    RAISE EXCEPTION 'you cannot review % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  INSERT INTO authz.reviews (object_type, object_id, created_by, closes_at)
  VALUES (p_type, p_id, authz.uid()::text, p_closes_at) RETURNING id INTO v_id;
  INSERT INTO authz.review_items (review_id, item, relation, subject_type, subject_id, subject_relation, expires_at)
  SELECT v_id, row_number() OVER (ORDER BY g.created_at, g.relation, g.subject_type, g.subject_id), g.relation,
         g.subject_type, g.subject_id, g.subject_relation, g.expires_at
  FROM authz.shares g WHERE g.object_type = p_type AND g.object_id = p_id;
  PERFORM authz_int.audit('start_review', p_type, p_id, NULL, NULL, NULL, NULL, jsonb_build_object('review', v_id));
  RETURN v_id;
END $f$;

CREATE OR REPLACE FUNCTION authz.review_items(p_review bigint)
RETURNS TABLE (item int, relation text, subject_type text, subject_id text, subject_relation text,
               expires_at timestamptz, keep boolean, decided_by text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.reviews;
BEGIN
  PERFORM authz_int.users_only('authz.review_items');
  SELECT * INTO v FROM authz.reviews WHERE id = p_review;
  IF v.id IS NULL OR NOT authz_int.may_inspect(v.object_type, v.object_id) THEN
    RAISE EXCEPTION 'you cannot see review %', p_review USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT i.item, i.relation, i.subject_type,
    CASE WHEN i.subject_type = 'link' THEN '(link)' ELSE i.subject_id END, i.subject_relation, i.expires_at, i.keep,
    i.decided_by FROM authz.review_items i WHERE i.review_id = p_review ORDER BY i.item;
END $f$;

CREATE OR REPLACE FUNCTION authz.review_decide(p_review bigint, p_item int, p_keep boolean) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.reviews; i authz.review_items;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.review_decide');
  SELECT * INTO v FROM authz.reviews WHERE id = p_review AND closed_at IS NULL;
  IF v.id IS NULL OR NOT authz_int.may_inspect(v.object_type, v.object_id) THEN
    RAISE EXCEPTION 'you cannot decide in review %', p_review USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  SELECT * INTO i FROM authz.review_items WHERE review_id = p_review AND item = p_item;
  IF i.item IS NULL THEN RAISE EXCEPTION 'no item % in review %', p_item, p_review USING HINT = 'rowstile help AZ708'; END IF;
  IF NOT authz_int.may_manage(v.object_type, v.object_id, i.relation,
                              authz_int.subject_key(i.subject_type, i.subject_id, i.subject_relation)) THEN
    RAISE EXCEPTION 'you cannot decide on % in review % (you could not unshare it)', i.relation, p_review
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  UPDATE authz.review_items SET keep = p_keep, decided_by = authz.uid()::text, decided_at = now()
  WHERE review_id = p_review AND item = p_item;
END $f$;

-- Close: revoke what reviewers marked (and, if asked, whatever nobody decided and you could unshare)
CREATE OR REPLACE FUNCTION authz.close_review(p_review bigint, p_revoke_undecided boolean DEFAULT false) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.reviews; n int;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.close_review');
  SELECT * INTO v FROM authz.reviews WHERE id = p_review AND closed_at IS NULL FOR UPDATE;
  IF v.id IS NULL OR NOT authz_int.may_inspect(v.object_type, v.object_id) THEN
    RAISE EXCEPTION 'you cannot close review %', p_review USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  PERFORM set_config('authz_ctx.reason', 'access review ' || p_review, true);
  -- items marked 'revoke' were decided by someone allowed to unshare them; undecided ones need you to be
  DELETE FROM authz.shares g USING authz.review_items i
  WHERE i.review_id = p_review
    AND (i.keep = false OR (p_revoke_undecided AND i.keep IS NULL
         AND authz_int.may_manage(v.object_type, v.object_id, i.relation,
                                  authz_int.subject_key(i.subject_type, i.subject_id, i.subject_relation))))
    AND g.object_type = v.object_type AND g.object_id = v.object_id AND g.relation = i.relation
    AND g.subject_type = i.subject_type AND g.subject_id = i.subject_id AND g.subject_relation = i.subject_relation;
  GET DIAGNOSTICS n = ROW_COUNT;
  UPDATE authz.reviews SET closed_at = now() WHERE id = p_review;
  PERFORM authz_int.audit('close_review', v.object_type, v.object_id, NULL, NULL, NULL, NULL,
                          jsonb_build_object('review', p_review, 'revoked', n));
  RETURN n;
END $f$;

-- Leaks: SELECT * FROM authz.lint()  (administrators; run after schema changes)
CREATE OR REPLACE FUNCTION authz.lint() RETURNS TABLE (severity text, object text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r record; v_role oid := to_regrole('starter_app');
BEGIN
  IF v_role IS NULL THEN
    severity := 'error'; object := 'starter_app'; problem := 'the app role does not exist'; RETURN NEXT; RETURN;
  END IF;
  -- the app role itself
  FOR r IN SELECT rolsuper, rolbypassrls FROM pg_roles WHERE oid = v_role AND (rolsuper OR rolbypassrls) LOOP
    severity := 'error'; object := 'starter_app';
    problem := 'is a superuser or has BYPASSRLS: row-level security does not apply to it at all'; RETURN NEXT;
  END LOOP;
  FOR r IN SELECT p.oid::regrole AS parent FROM pg_roles p
           WHERE p.oid <> v_role AND (p.rolsuper OR p.rolbypassrls) AND pg_has_role(v_role, p.oid, 'MEMBER') LOOP
    severity := 'error'; object := 'starter_app';
    problem := format('is a member of %s, which bypasses row-level security', r.parent); RETURN NEXT;
  END LOOP;
  -- rowstile's own objects: nobody but the owner uses them, except for what the policy grants
  FOR r IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = 'starter_app'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = 'starter_app'::regrole AND c.relnamespace = 'authz_gen'::regnamespace AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, 'starter_app'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = 'starter_app'::regrole)
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = 'starter_app'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.create_role(text, bigint, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.roles_of(text, bigint)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.start_review(text, bigint, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.can(text, bigint, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.perms(text, bigint)']::regprocedure[])) LOOP
    severity := 'error'; object := r.object;
    problem := format('%s holds %s on it, which the policy doesn''t give (a default privilege of the owner, or a grant made since the last apply): the next apply takes it back, or %s', r.who, r.privilege, r.stmt);
    RETURN NEXT;
  END LOOP;
  -- schemas on the search path of the functions that run as the owner, which others may create in
  FOR r IN SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(authz_int.policy_path()) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_' LOOP
    severity := 'error'; object := r.schema;
    problem := format('is on the search path of rowstile''s functions that run as the owner, and %s may create in it: a function there can take the place of a built-in one and run as the owner. REVOKE CREATE ON SCHEMA %I FROM %s, or apply with a search path without it', r.who, r.schema, r.who);
    RETURN NEXT;
  END LOOP;
  -- the audit trail's guard, which fires in every replication role (ENABLE ALWAYS): ENABLE TRIGGER ALL, which a
  -- data-only pg_restore --disable-triggers ends with, puts it back for ordinary sessions only
  FOR r IN SELECT t.name, g.tgenabled::text AS mode
           FROM (VALUES ('authz_audit_append_only'), ('authz_audit_no_truncate')) t (name)
           LEFT JOIN pg_trigger g ON g.tgrelid = 'authz.audit'::regclass AND g.tgname = t.name
           WHERE g.tgenabled IS DISTINCT FROM 'A' LOOP
    severity := 'warning'; object := 'authz.audit';
    problem := format('the trigger %s %s. rowstile reapply puts it back, in every replication role', r.name,
      CASE r.mode
        WHEN 'O' THEN 'guards it in ordinary sessions only: one with session_replication_role = replica may change the trail (ENABLE TRIGGER ALL leaves it so, as at the end of a data-only pg_restore --disable-triggers)'
        WHEN 'R' THEN 'guards it with session_replication_role = replica only: an ordinary session may change the trail'
        WHEN 'D' THEN 'that guards it is off: the trail may be changed'
        ELSE 'that guards it is missing: the trail may be changed' END);
    RETURN NEXT;
  END LOOP;
  -- governed tables
  FOR r IN SELECT c.oid::regclass AS tbl, c.relrowsecurity, c.relforcerowsecurity, c.relowner,
                  c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x) AS governed
           FROM pg_class c WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"', '"app"."teams"', '"app"."users"']::text[]) x) LOOP
    IF r.relowner = v_role OR pg_has_role(v_role, r.relowner, 'MEMBER') THEN
      IF NOT r.relforcerowsecurity THEN
        severity := 'error'; object := r.tbl::text;
        problem := format('is owned by %s (or a role it belongs to): owners skip row-level security unless you ALTER TABLE %s FORCE ROW LEVEL SECURITY', 'starter_app', r.tbl);
        RETURN NEXT;
      END IF;
    END IF;
    IF NOT r.relrowsecurity AND r.governed THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('row-level security is off, so the policy''s rules don''t apply to it: %s reads and writes every row it has privileges on. Apply the policy again (it turns it on), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', 'starter_app', r.tbl);
      RETURN NEXT;
    ELSIF NOT r.relrowsecurity AND has_table_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row (the policy has no rules for this table): fine for a directory, otherwise add rules', 'starter_app');
      RETURN NEXT;
    END IF;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', 'starter_app', r.tbl, 'starter_app');
      RETURN NEXT;
    END IF;
  END LOOP;
  -- policies on governed tables that rowstile didn't make (left from before, or made by a migration) and that
  -- apply to the app role: Postgres joins permissive policies with OR, so one widens what the rules allow
  FOR r IN SELECT p.polname, p.polrelid::regclass AS tbl, p.polpermissive,
                  CASE p.polcmd WHEN 'r' THEN 'select' WHEN 'a' THEN 'insert' WHEN 'w' THEN 'update'
                                WHEN 'd' THEN 'delete' ELSE 'every command' END AS cmd
           FROM pg_policy p
           LEFT JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
           WHERE p.polrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             AND coalesce(d.description, '') NOT IN ('rowstile', 'rowfence', 'authzc')
             AND p.polname NOT IN ('authz_select', 'authz_insert', 'authz_update', 'authz_delete')
             AND EXISTS (SELECT 1 FROM unnest(p.polroles) o
                         WHERE CASE WHEN o = 0 THEN true ELSE pg_has_role(v_role, o, 'MEMBER') END)
           ORDER BY p.polrelid::regclass::text, p.polname LOOP
    object := r.tbl::text;
    IF r.polpermissive THEN
      severity := 'error';
      problem := format('the policy %I (%s) on it is not rowstile''s: Postgres joins a table''s policies with OR, so it lets %s through whatever the rules say. DROP POLICY %I ON %s, and say what it allowed in the policy file', r.polname, r.cmd, 'starter_app', r.polname, r.tbl);
    ELSE
      severity := 'info';
      problem := format('the restrictive policy %I (%s) on it is not rowstile''s: %s gets less than the rules give, and a write it refuses fails with Postgres''s own message, not a reason', r.polname, r.cmd, 'starter_app');
    END IF;
    RETURN NEXT;
  END LOOP;
  -- tables beside the policy's (in their schemas) that it doesn't name: nothing filters what the app role reads there
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind IN ('r', 'p') AND NOT c.relispartition AND NOT c.relrowsecurity
             AND c.relnamespace IN (SELECT k.relnamespace FROM unnest(ARRAY['"app"."documents"', '"app"."teams"', '"app"."users"', '"app"."team_members"']::text[]) x
                                    JOIN pg_class k ON k.oid = to_regclass(x))
             AND c.oid NOT IN (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"app"."documents"', '"app"."teams"', '"app"."users"', '"app"."team_members"']::text[]) x
                               WHERE to_regclass(x) IS NOT NULL)
             AND has_any_column_privilege(v_role, c.oid, 'SELECT')
           ORDER BY c.oid::regclass::text LOOP
    severity := 'info'; object := r.tbl::text;
    problem := format('%s may read every row, and the policy doesn''t name this table: fine for a lookup table, otherwise give it a type and rules', 'starter_app');
    RETURN NEXT;
  END LOOP;
  -- partitions and inheritance children: used directly, they skip the rules and the triggers of the table above
  -- (apply turns row-level security on for the ones there are then; later ones are found here)
  FOR r IN WITH RECURSIVE d(oid, top, governed) AS (
             SELECT i.inhrelid, i.inhparent, x.governed FROM pg_inherits i
             JOIN (SELECT to_regclass(t) AS tbl, true AS governed FROM unnest(ARRAY['"app"."documents"']::text[]) t
                   UNION ALL SELECT to_regclass(t), false FROM unnest(ARRAY['"app"."team_members"']::text[]) t) x
               ON i.inhparent = x.tbl
             UNION SELECT i.inhrelid, d.top, d.governed FROM pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass AS part, d.top::regclass AS tbl, d.governed, k.relrowsecurity
           FROM d JOIN pg_class k ON k.oid = d.oid LOOP
    IF has_table_privilege(v_role, r.part, 'TRUNCATE') THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may TRUNCATE it, which skips row-level security and %s''s triggers: REVOKE TRUNCATE ON %s FROM %s', r.tbl, 'starter_app', r.tbl, r.part, 'starter_app');
      RETURN NEXT;
    END IF;
    IF NOT r.relrowsecurity AND (has_table_privilege(v_role, r.part, 'INSERT') OR has_table_privilege(v_role, r.part, 'UPDATE')
                                 OR has_table_privilege(v_role, r.part, 'DELETE')
                                 OR (r.governed AND has_table_privilege(v_role, r.part, 'SELECT'))) THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may use it directly, without %s''s rules or the triggers that keep inheritance and the audit current: apply the policy again (it turns row-level security on for it), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', r.tbl, 'starter_app', r.tbl, r.part);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- tables that inherit (not partitions), made since the last apply: Postgres runs a table's row triggers for
  -- its own rows only, and applying gives them to each table under it (whatever the app role may do there:
  -- written through the table above, their rows need no privilege of their own)
  FOR r IN SELECT c.child, string_agg(c.name::text, ', ' ORDER BY c.name) AS names
           FROM authz_int.child_triggers() c GROUP BY c.child LOOP
    severity := 'error'; object := r.child::text;
    problem := format('inherits from a table the policy has rules or a type for, and was made since the policy was last applied: Postgres runs a table''s row triggers for its own rows only, so a rule on a column is not checked on the rows stored here, and their shares stay when their key changes (missing here: %s). Apply the policy again (it makes them)', r.names);
    RETURN NEXT;
  END LOOP;
  -- unique constraints on governed tables tell people that rows they cannot see exist
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisunique AND NOT i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             AND has_table_privilege(v_role, i.indrelid, 'INSERT') LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('a unique index on %s: inserting a duplicate fails even when the existing row is hidden, which tells the user it exists', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- primary keys the app role may choose (a column it may insert or update, not GENERATED ALWAYS): the same
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             AND EXISTS (SELECT 1 FROM pg_attribute a
                         WHERE a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey) AND a.attidentity <> 'a'
                           AND (has_column_privilege(v_role, i.indrelid, a.attnum, 'INSERT')
                                OR has_column_privilege(v_role, i.indrelid, a.attnum, 'UPDATE'))) LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('the primary key of %s, which %s may choose: an insert with the id of a hidden row fails, which tells the user it exists. Let the database make the ids (GENERATED ALWAYS AS IDENTITY, or random uuids), or revoke INSERT and UPDATE on the key', r.tbl, 'starter_app');
    RETURN NEXT;
  END LOOP;
  -- masked columns must only be readable through their view
  FOR r IN SELECT m.tbl, m.col, m.view FROM authz_int.masked_columns m
           WHERE CASE WHEN EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(m.tbl) AND a.attname = m.col
                                   AND a.attnum > 0 AND NOT a.attisdropped)
                      THEN has_column_privilege(v_role, m.tbl, m.col, 'SELECT') ELSE false END LOOP
    severity := 'error'; object := to_regclass(r.tbl)::text || '.' || r.col;
    problem := format('the policy masks it, but %s may read it from the table (a GRANT to the role, a role it belongs to, or PUBLIC): read it through %s and revoke that', 'starter_app', r.view);
    RETURN NEXT;
  END LOOP;
  -- tables holding relationships (memberships, links) the app role may change directly
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.readers, v.typed
           FROM (VALUES ('"app"."team_members"', 'team.member', false)) v(tbl, readers, typed) LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which empties memberships without row-level security: REVOKE TRUNCATE ON %s FROM %s', 'starter_app', r.tbl, 'starter_app');
      RETURN NEXT;
    END IF;
    IF (has_table_privilege(v_role, r.tbl, 'INSERT') OR has_table_privilege(v_role, r.tbl, 'UPDATE')
        OR has_table_privilege(v_role, r.tbl, 'DELETE'))
       AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl) THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may change it, and it decides who is in what: anyone could add themselves. Revoke the write privileges, or give it rules', 'starter_app');
      RETURN NEXT;
    END IF;
    -- ... or read in full: who is linked to what (a type's table without rules is named above)
    IF NOT r.typed AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl)
       AND has_any_column_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row, and the policy reads it for %s: who is linked to what is readable. Fine where that is no secret, otherwise give it a type and rules', 'starter_app', r.readers);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- columns that grant a relation, changed by anyone who may update the row
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, what, loc, ask)
           WHERE tbl IS NOT NULL LOOP
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attname = r.col
               AND a.attnum > 0 AND NOT a.attisdropped)
       AND has_column_privilege(v_role, r.tbl, r.col, 'UPDATE') THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('grants %s (%s), and anyone who may update the row may change it: add a rule such as "update %s : %s"', r.what, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.ask);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- rules for a command the app role has no privilege for (one column's is enough for a read, an insert or
  -- an update: the app may write some columns only)
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.cmd FROM (VALUES ('"app"."documents"', 'delete'), ('"app"."documents"', 'insert'), ('"app"."documents"', 'select'), ('"app"."documents"', 'update')) v(tbl, cmd)
           WHERE v.tbl IS NOT NULL LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF r.cmd = 'delete' THEN
      CONTINUE WHEN has_table_privilege(v_role, r.tbl, 'DELETE');
    ELSE
      CONTINUE WHEN has_any_column_privilege(v_role, r.tbl, r.cmd);
    END IF;
    severity := 'warning'; object := r.tbl::text;
    problem := format('the policy has a rule for %s, but %s has no %s privilege on the table: the rule never applies, and the statement fails with Postgres''s own "permission denied for table". GRANT %s ON %s TO %s, or make the rule "%s : nobody"', r.cmd, 'starter_app', upper(r.cmd), upper(r.cmd), r.tbl, 'starter_app', r.cmd);
    RETURN NEXT;
  END LOOP;
  -- relations named like a type that signs in
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text)) v(type, rel, loc)
           WHERE type IS NOT NULL LOOP
    severity := 'info'; object := r.type || '.' || r.rel;
    problem := format('is named like the type %s (%s), which signs in: alone in a rule it reads like any %s, and it is this row''s. A name that says what the relation is (author, owner) reads better', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.rel);
    RETURN NEXT;
  END LOOP;
  -- columns that move a row under another, with nothing checking where it moves to
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, rel, loc)
           WHERE tbl IS NOT NULL LOOP
    -- (a composite key's columns are 'org_id, parent_id': any of them it may update)
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attnum > 0 AND NOT a.attisdropped
               AND a.attname::text = ANY (string_to_array(r.col, ', ')) AND has_column_privilege(v_role, r.tbl, a.attnum, 'UPDATE')) THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('moves a row under another (%s, %s), and nothing checks where it moves to, so anyone who may update a row may put it inside something they may not change: add a rule such as "update %s after : %s.edit"', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.rel);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- views over governed tables that run with their owner's rights
  FOR r IN SELECT DISTINCT v.oid::regclass AS view, d.refobjid::regclass AS tbl
           FROM pg_depend d JOIN pg_rewrite w ON w.oid = d.objid JOIN pg_class v ON v.oid = w.ev_class
           LEFT JOIN pg_description ds ON ds.objoid = v.oid AND ds.classoid = 'pg_class'::regclass
           WHERE d.classid = 'pg_rewrite'::regclass AND d.refclassid = 'pg_class'::regclass
             AND d.refobjid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"', '"app"."teams"', '"app"."users"', '"app"."team_members"']::text[]) x)
             AND v.oid <> d.refobjid AND v.relkind IN ('v', 'm')
             AND v.relnamespace NOT IN (to_regnamespace('authz_gen'), to_regnamespace('authz_int'))
             AND coalesce(ds.description, '') NOT IN ('rowstile masked view', 'rowfence masked view', 'authzc masked view')
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=true'], false)
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=on'], false)
             AND has_table_privilege(v_role, v.oid, 'SELECT') LOOP
    severity := 'error'; object := r.view::text;
    problem := format('%s may read this view of %s, and views run with their owner''s rights, so row-level security does not apply: ALTER VIEW %s SET (security_invoker = on)', 'starter_app', r.tbl, r.view);
    RETURN NEXT;
  END LOOP;
  -- functions that read governed tables as their owner
  FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p
           WHERE p.prosecdef AND p.pronamespace NOT IN (to_regnamespace('authz'), to_regnamespace('authz_int'),
                                                       to_regnamespace('authz_gen'), 'pg_catalog'::regnamespace)
             AND has_function_privilege(v_role, p.oid, 'EXECUTE')
             AND p.prokind IN ('f', 'p')
             AND EXISTS (SELECT 1 FROM unnest(ARRAY['app.documents', 'app.teams', 'app.users', 'app.team_members']::text[]) x
                         WHERE lower(replace(pg_get_functiondef(p.oid), '"', '')) ~
                               ('(from|join|update|into|table|only)\s+(' || lower(split_part(x, '.', 1)) || '\.)?'
                                || lower(split_part(x, '.', 2)) || '([^a-z0-9_$]|$)')) LOOP
    severity := 'warning'; object := r.fn::text;
    problem := 'SECURITY DEFINER, callable by the app role, and seems to use a governed table: it reads rows without row-level security unless its owner is subject to it';
    RETURN NEXT;
  END LOOP;
  -- lookups the permission views make
  FOR r IN SELECT * FROM (VALUES ('"app"."users"', 'id', 'user: find one by its key, for checks and write rules', NULL), ('"app"."team_members"', 'team_id', 'team.member: find the members of an object', NULL), ('"app"."team_members"', 'user_id', 'team.member: find what a subject is in', NULL), ('"app"."teams"', 'id', 'team: find one by its key, for checks and write rules', NULL), ('"app"."documents"', 'owner_id', 'document.owner: find objects by owner_id', NULL), ('"app"."documents"', 'id', 'document: find one by its key, for checks and write rules', NULL)) v(tbl, col, why, alone) WHERE tbl IS NOT NULL LOOP
    CONTINUE WHEN to_regclass(r.tbl) IS NULL;
    -- a plain view can't have an index: the tables under it answer the lookups
    CONTINUE WHEN (SELECT c.relkind FROM pg_class c WHERE c.oid = to_regclass(r.tbl)) = 'v';
    -- an index whose first columns are these (one, or a composite key's, in any order), or what serves a (type, id)
    -- pair alone (its ids where they are two columns, its type where its id is one): a finished one, with no
    -- condition (the lookups are joins, which a partial index doesn't serve), as rowstile indexes counts them
    IF NOT EXISTS (SELECT 1 FROM pg_index i, unnest(ARRAY[r.col, r.alone]) w(cs)
                   WHERE w.cs IS NOT NULL AND i.indrelid = to_regclass(r.tbl) AND i.indisvalid AND i.indpred IS NULL
                     AND (SELECT array_agg(a.attname::text ORDER BY a.attname)
                          FROM unnest((i.indkey::int2[])[0:cardinality(string_to_array(w.cs, ', ')) - 1]) k
                          JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k)
                         = (SELECT array_agg(c ORDER BY c) FROM unnest(string_to_array(w.cs, ', ')) c)) THEN
      severity := 'performance'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('no index starts with %s (%s): CREATE INDEX ON %s (%s)',
                        CASE WHEN r.col LIKE '%, %' THEN 'these columns' ELSE 'this column' END, r.why, to_regclass(r.tbl),
                        (SELECT string_agg(quote_ident(c), ', ') FROM unnest(string_to_array(r.col, ', ')) c));
      RETURN NEXT;
    END IF;
  END LOOP;
END $f$;

-- Tables that inherit from a table with rules or a type (not partitions: Postgres gives those their table's row
-- triggers itself): the row triggers made above, on each, for the rows stored there
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = 'starter_app'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = 'starter_app'::regrole AND c.relnamespace = 'authz_gen'::regnamespace AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, 'starter_app'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = 'starter_app'::regrole)
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = 'starter_app'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.create_role(text, bigint, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.roles_of(text, bigint)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.start_review(text, bigint, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.can(text, bigint, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.perms(text, bigint)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO starter_app;

GRANT SELECT ON ALL TABLES IN SCHEMA authz_gen TO starter_app;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA authz_gen TO starter_app;

