  authz.uid(),
  authz.principal(),
  authz.ctx(text),
  authz.link_hashes(),
  authz.act_as(text, text),
  authz.connection_check(),
  authz.can(text, text, text),
  authz.list(text, text, text, integer),
  authz.perms(text, text),
  authz.perms_of(text, text[]),
  authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb),
  authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb),
  authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb),
  authz.unshare(text, text, text, text, text, text),
  authz.unshare(text, bigint, text, text, bigint, text),
  authz.unshare(text, bigint, text, text, text, text),
  authz.create_link(text, text, text, timestamptz),
  authz.create_link(text, bigint, text, timestamptz),
  authz.list_links(text, text),
  authz.revoke_link(text, text, text),
  authz.create_role(text, text, text, text, text[]),
  authz.create_role(text, bigint, text, text, text[]),
  authz.set_role_permissions(bigint, text[]),
  authz.delete_role(bigint),
  authz.roles_of(text, text),
  authz.roles_of(text, bigint),
  authz.who(text, text, text),
  authz.explain(text, text, text, text),
  authz.list_shares(text, text),
  authz.explain_rule(text, text, text, jsonb),
  authz.who_among(text, text, text, text[], text),
  authz.create_api_key(text, text, timestamptz, text, text),
  authz.list_api_keys(text, text),
  authz.revoke_api_key(bigint),
  authz.login_key(text),
  authz.login_jwt(text),
  authz.view_as(text, text),
  authz.request_access(text, text, text, text, interval),
  authz.request_access(text, bigint, text, text, interval),
  authz.pending_requests(),
  authz.decide_request(bigint, boolean, text),
  authz.cancel_request(bigint),
  authz.break_glass(text, text, text, text, interval),
  authz.break_glass(text, bigint, text, text, interval),
  authz.start_review(text, text, timestamptz),
  authz.start_review(text, bigint, timestamptz),
  authz.review_items(bigint),
  authz.review_decide(bigint, integer, boolean),
  authz.close_review(bigint, boolean),
  authz.who(text, bigint, text),
  authz.explain(text, bigint, text, text),
  authz.list_shares(text, bigint),
  authz.list_links(text, bigint),
  authz.revoke_link(text, bigint, text),
  authz.can(text, bigint, text),
  authz.who_among(text, bigint, text, text[], text),
  authz.perms(text, bigint)
  TO starter_app;

-- Tables never analyzed (made just now, or too small for autovacuum to have reached them) are planned
-- as ten pages of rows: a table of 6 rows as thousands. Through the rules' lookups that becomes an estimate of
-- hundreds of thousands, and Postgres compiles (JIT) and plans for reads of a few rows. ANALYZE reads a
-- sample (30,000 rows at most) and blocks neither reads nor writes.
DO $an$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind = 'r' AND c.relpersistence <> 't' AND c.reltuples < 0
             AND pg_has_role(c.relowner, 'USAGE')
             AND (c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_int'))
                  OR c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."users"', '"app"."teams"', '"app"."team_members"', '"app"."documents"']::text[]) x)) LOOP
    EXECUTE format('ANALYZE %s', r.tbl);
  END LOOP;
END $an$;

-- the policy now in force
INSERT INTO authz.policy_versions (action, policy, files, version, lock)
VALUES ('apply', $authz_policy$-- Who may see and change a document. Everything that grants access is in this file.
-- After a change: rowstile check, then rowstile dev (or push and test), then rowstile migrate.
app role starter_app

type user = app.users

type team = app.teams
  member : user = app.team_members(team_id -> user_id)

type document = app.documents
  owner  : user = owner_id
  editor : user, team#member shared  -- given with authz.share(), by whoever may share
  viewer : user, team#member shared

  can share = owner
  can edit  = share or editor
  can view  = edit or viewer

rules app.documents
  select          : view
  insert          : owner
  update          : edit
  update owner_id : nobody
  delete          : share
$authz_policy$,
  $authz_files${}$authz_files$::jsonb, '0.1.0-alpha.9', '64fa4b0cce59c2f2');
